drawFloor(ctx, pal, camX, pulse, ceilOn);
visB.length = 0; visS.length = 0; visO.length = 0;
const B = L.buckets, lo = Math.max(0, Math.floor(camX) + 1), hi = Math.min(B.length - 1, Math.floor(camX + W / U) + 4);
for (let b = lo; b <= hi; b++) {
const arr = B[b];
for (let i = 0; i < arr.length; i++) {
const o = arr[i];
if (o.t === 'block') visB.push(o); else if (o.t === 'spike') visS.push(o); else visO.push(o);
}
}
for (const o of visO) {
if (o.t === 'phase') drawGate(ctx, (o.x - camX) * U, FORM_COL[o.r] || FORM_COL[0], 'phase', o.r, pulse, animT);
else if (o.t === 'speed') drawGate(ctx, (o.x - camX) * U, SPEED_COL[o.r] || SPEED_COL[1], 'speed', o.r, pulse, animT);
}
const fx = (L.finishX - camX) * U;
