ctx.shadowColor = PALS[LEVELS[sel].pal].prim; ctx.shadowBlur = 22;
txt(ctx, 'BEATLINE', W / 2, 156, 64, FONT_D, UI.head, 'center', 560);
ctx.restore();
txt(ctx, 'Six neon tracks. Every hazard lands on the beat.', W / 2, 212, 19, FONT_B, UI.body, 'center', 560, '700');
txt(ctx, isTouch ? 'Tap to jump, glide and flip. Hold to keep jumping.' : 'One button: Space, Up or click. Hold to keep jumping.', W / 2, 244, 16, FONT_B, UI.body, 'center', 560, '600');
