const C_LINK = '#1FD8FF', C_RUN = '#7CFFCB', C_CORE = '#FF3DCB', C_ENTRY = '#5AA9FF';
const C_SEN = '#FF4D5E', C_HUN = '#FFB13D', C_SCN = '#B46BFF', C_FW = '#FF7A3D';
const C_CACHE = '#FFD84D', C_PROXY = '#3DFFD8', C_CIPH = '#8CFF5A', C_LOCK = '#7FA8FF';
