(def.e || []).forEach(s => {
const kc = s[0], body = s.slice(2);
if (kc === 's' || kc === 'z') en.push({ k: kc === 's' ? K_SEN : K_HID, nodes: labs(body) });
else if (kc === 'u') en.push({ k: K_HUN, home: lab(body[0]) });
else if (kc === 'x') {
const parts = body.split('/');
en.push({ k: K_SCN, home: lab(parts[0]), sets: parts.slice(1).map(labs) });
}
});
const prog = [0, 0, 0, 0, 0, 0];
const ps = def.p || '';
for (let k = 0; k < 6 && k < ps.length; k++) prog[k] = +ps[k] || 0;
