if (t === T_D) { S[fo] |= NF_USED; S[O_CACHE]++; if (ev) ev('cache', b, 0); }
else if (t === T_H) { S[fo] |= NF_USED | NF_REV; addTrace(S, TR_HONEY); if (ev) ev('honey', b, 0); }
