if ((run.type === 'hunt' || run.type === 'swarm' || run.type === 'boss') && e.kind <= 2 && !netBy && Math.random() < 0.14) spawnPick(Math.random() < 0.7 ? 0 : 1, e.p.x, e.p.y, e.p.z, 25);
