smokePuff(fp.x, fp.y + 1, fp.z, 1, 3.2, true, 2.4);
FX.spawn(fp.x + rnd(0.8), fp.y + 0.6, fp.z + rnd(0.8), rnd(1), 3 + Math.random() * 3, rnd(1), 0.5, 2.2, 0.6, 1, 0.55, 0.2, 0.9, 2, 0.5);
