r.waveT -= h;
if (r.waveT <= 0) {
r.wave++; r.waveOn = true;
r.pend[0] = 2 + r.wave; r.pend[1] = Math.floor(r.wave * 0.75); r.pend[2] = r.wave >= 4 ? Math.floor((r.wave - 2) / 2) : 0;
waveGo(r.wave);
}
