txt(ctx, 'Race the gates, hunt rogue drones, land stunts under rock arches, take down the carrier.', cx, VH - 52, 14, FONT_B, UI.body, 'center', VW - 60);
txt(ctx, 'W/S pitch   A/D roll   Q/E yaw   Space guns   F missile   Shift boost   C airbrake   V camera', cx, VH - 28, 12, FONT_M, UI.dim, 'center', VW - 60);
