v.fromBufferAttribute(pa, j).applyMatrix4(e.m);
pos[o * 3] = v.x; pos[o * 3 + 1] = v.y; pos[o * 3 + 2] = v.z;
v.fromBufferAttribute(na, j).applyMatrix3(nm).normalize();
