const stats = [
['Max speed', Math.round(kmh) + ' km/h'], ['Max +G', R.maxPos.toFixed(1) + ' G'],
['Max -G', R.maxNeg.toFixed(1) + ' G'], ['Airtime', R.air.toFixed(1) + ' s'],
['Length', Math.round(path.pieceLen) + ' m'], ['Duration', fmtTime(R.t)],
['Inversions', String(R.inv)], ['Biggest drop', Math.round(R.drop) + ' m'],
];
