const keys = {};
function update(dt) {
animT += dt;
if (toastT > 0) toastT -= dt;
if (shakeAmt > 0) shakeAmt = Math.max(0, shakeAmt - dt * 2.5);
updateConfetti(dt);
if (mode === 'over') overT += dt;
if (paused) return;
if (stallMark > 0) stallMark -= dt;
if (ride.on && path) {
if (!ride.done) {
ride.acc += dt;
let steps = 0;
while (ride.acc >= SUB && steps < 8 && !ride.done) { rideStep(SUB); ride.acc -= SUB; steps++; }
if (steps >= 8) ride.acc = 0;
if (ride.t > 240 && !ride.done) ride.done = 'stall';
rideFx(dt);
} else {
ride.doneT += dt;
if (ride.doneT > (ride.done === 'stall' ? 0.3 : 0.9)) finishRide();
}
}
updateParticles(dt);
if (mode !== 'title' && !(mode === 'playing' && sub === 'ride') && !menu) {
const yi = (keys.KeyE ? 1 : 0) - (keys.KeyQ ? 1 : 0);
const pi = (keys.KeyR || keys.ArrowUp ? 1 : 0) - (keys.KeyF || keys.ArrowDown ? 1 : 0);
const zi = (keys.KeyX ? 1 : 0) - (keys.KeyZ ? 1 : 0);
cam.yaw += yi * 1.7 * dt;
cam.pitch = clamp(cam.pitch + pi * 1.1 * dt, 0.08, 1.45);
cam.dist = clamp(cam.dist * Math.exp(zi * 1.4 * dt), 16, 260);
}
}

function render(dt) {
const building = mode === 'playing' && sub === 'build';
ghost.mesh.visible = building && !complete;
ghostTiles.visible = building && !complete;
endArrow.visible = building && !complete;
bufferStop.visible = pieces.length > 0 && !complete;
if (building) {
ghostMat.opacity = 0.36 + 0.14 * Math.sin(animT * 5);
endArrow.position.set(endPos.x, endPos.y + 3.2 + Math.sin(animT * 4) * 0.35, endPos.z);
}
placeTrain();
if (mode === 'title') {
titleYaw += dt * 0.06;
V4.set(PLOT / 2, 8, PLOT / 2 - 10);
const d = 205, cp = Math.cos(0.42);
camera.position.set(V4.x + cp * Math.cos(titleYaw) * d, V4.y + Math.sin(0.42) * d, V4.z + cp * Math.sin(titleYaw) * d);
camera.up.set(0, 1, 0); camera.lookAt(V4);
setFov(55);
} else if (mode === 'playing' && sub === 'ride' && ride.on && path) {
rideCamera(dt);
} else {
if (mode === 'over') cam.yaw += dt * 0.07;
if (stallMark > 0) V4.copy(stallPos); else V4.copy(endPos);
if (camSnapToEnd) { camTgt.copy(V4); camSnapToEnd = false; }
orbitCam(dt, 5);
setFov(60);
}
if (shakeAmt > 0 && !paused) {
const a = shakeAmt * 0.35;
camera.position.x += (Math.random() * 2 - 1) * a; camera.position.y += (Math.random() * 2 - 1) * a; camera.position.z += (Math.random() * 2 - 1) * a;
}
sky.position.copy(camera.position);
renderer.render(scene, camera);
drawHUD();
}

let cw = 1, ch = 1, hudDpr = 1, hs = 1, LW = 960, LH = 600, mx = -1, my = -1;
