ctx.fillStyle = 'rgba(255, 93, 93, 0.75)'; ctx.fillRect(x, y6, w, y45 - y6);
ctx.fillStyle = 'rgba(75, 227, 160, 0.55)'; ctx.fillRect(x, y45, w, y02 - y45);
ctx.fillStyle = 'rgba(45, 212, 192, 0.85)'; ctx.fillRect(x, y02, w, ym2 - y02);
