ctx.fillRect(x, yy - 1.5, w, 3);
txt(ctx, gv.toFixed(1), x + w / 2, y + h + 13, 14, FONT_M, gv < 0.2 ? UI.teal : gv > 4.5 ? UI.danger : UI.head, 'center', w + 20, '700');
