const RB = 24, FAST = { fast: true }, REL = {};
const NET = { s: null, role: '', me: 0, opp: 1, oi: 1, oiK: false, names: ['Player 1', 'Player 2'], tok: 0, opening: false, openT: 0, hb: 0, q: [],
ready: false, pend: false, away: false, lastRx: 0, wd: 0, note: '', noteOk: false, rec: false, g: 8, r: 2, v: 0, fb: 0,
tid: 0, nr: false, menu: false, mf: 0, again: [false, false], aimT: 0, aq: 0, raQ: 0, ra: 0, rsa: 0, rsb: 0, rp: 0, rv: 0,
rx: 0, rz: 0, rc: -1, cx: 0, cz: 0, bpT: 0, sb: 0, sc: 0, rest: null, pbT: 0, nT: 0, nAt: 0, sndT: 0,
rbH: 0, rbN: 0, rt: new Float64Array(RB), rm: new Int32Array(RB), rs1: new Float32Array(RB), rs2: new Float32Array(RB),
rbp: new Float64Array(RB * 32), bx: new Float64Array(32), bm: 0 };
function num(v) { return typeof v === 'number' && isFinite(v); }
function r4(v) { return Math.round(v * 1e4) / 1e4; }
