glow(x1 - x0, 0.05, 0.08, (x0 + x1) / 2, top + 0.03, z0 + 0.04, c); glow(x1 - x0, 0.05, 0.08, (x0 + x1) / 2, top + 0.03, z1 - 0.04, c);
glow(0.08, 0.05, z1 - z0, x0 + 0.04, top + 0.03, (z0 + z1) / 2, c); glow(0.08, 0.05, z1 - z0, x1 - 0.04, top + 0.03, (z0 + z1) / 2, c);
