function sfxParry() { tone(1900, 0.18, { type: 'sine', vol: 0.08 }); tone(2850, 0.22, { type: 'sine', vol: 0.05, delay: 0.02 }); noise(0.05, { vol: 0.08, filter: 6000 }); }
