function sfxDeflect(perfect) { if (!sfxOk()) return; tone(perfect ? 2200 : 1500, 0.12, { type: 'sine', vol: 0.07, slide: perfect ? 3000 : 1900 }); }
function sfxHurt() { tone(140, 0.2, { type: 'sawtooth', vol: 0.09, slide: 60 }); noise(0.12, { vol: 0.1, filter: 900 }); }
function sfxDeath() { tone(300, 0.9, { type: 'sawtooth', vol: 0.08, slide: 40 }); noise(0.5, { vol: 0.08, filter: 600 }); }
function sfxDash() { if (!sfxOk()) return; noise(0.12, { vol: 0.07, filter: 2600 }); }
function sfxJump(k) { tone(k === 2 ? 520 : (k ? 660 : 420), 0.07, { type: 'triangle', vol: 0.04, slide: k ? 980 : 640 }); }
function sfxLand() { if (!sfxOk()) return; noise(0.05, { vol: 0.05, filter: 700 }); }
function sfxSlam() { noise(0.3, { vol: 0.16, filter: 500 }); tone(90, 0.25, { type: 'sine', vol: 0.1, slide: 40 }); }
function sfxBoom() { if (!sfxOk()) return; noise(0.25, { vol: 0.12, filter: 700 }); }
function sfxDeny() { tone(180, 0.1, { type: 'square', vol: 0.04 }); }
function sfxFocusIn() { tone(600, 0.35, { type: 'sine', vol: 0.06, slide: 150 }); noise(0.3, { vol: 0.04, filter: 400 }); }
function sfxFocusCut(n) { noise(0.35, { vol: 0.16, filter: 5200 }); tone(2400, 0.3, { type: 'sawtooth', vol: 0.045, slide: 200 }); if (n) tone(180, 0.4, { type: 'sine', vol: 0.1, slide: 60, delay: 0.05 }); }
function sfxRank(r) { tone(500 + r * 110, 0.1, { type: 'triangle', vol: 0.05 }); tone(750 + r * 160, 0.14, { type: 'triangle', vol: 0.045, delay: 0.07 }); }
