function sfxCharge() { if (!sfxOk()) return; tone(500, 0.3, { type: 'sine', vol: 0.03, slide: 1400 }); }
function sfxShoot(s) { if (!sfxOk()) return; tone(s > 1.2 ? 260 : 420, 0.12, { type: 'square', vol: 0.04, slide: s > 1.2 ? 120 : 200 }); }
function sfxEngage() { tone(330, 0.12, { type: 'square', vol: 0.04 }); tone(440, 0.16, { type: 'square', vol: 0.04, delay: 0.1 }); }
function sfxClear() { tone(523, 0.1, { type: 'triangle', vol: 0.06 }); tone(659, 0.1, { type: 'triangle', vol: 0.06, delay: 0.09 }); tone(784, 0.2, { type: 'triangle', vol: 0.06, delay: 0.18 }); }
function sfxBossIntro() { tone(110, 0.8, { type: 'sawtooth', vol: 0.07, slide: 55 }); noise(0.6, { vol: 0.06, filter: 300 }); }
function sfxBossPhase() { tone(220, 0.5, { type: 'sawtooth', vol: 0.06, slide: 440 }); }
