tx('Reached ' + regionLabel(r.region) + (r.bosses ? '  \u00B7  ' + r.bosses + (r.bosses > 1 ? ' bosses' : ' boss') + ' beaten' : ''), VW / 2, y + 72, 14, FONT_B, UI.body, 'center', W - 40, 600);
tx(fmtInt(r.dist) + ' m', VW / 2, y + 116, 46, FONT_M, UI.head, 'center', W - 40, 700);
if (r.newBest) tx('New best!', VW / 2, y + 154, 22, FONT_D, UI.ok, 'center');
