hctx.setTransform(1, 0, 0, 1, 0, 0);
hctx.clearRect(0, 0, hud.width, hud.height);
hctx.setTransform(dpr * hudK, 0, 0, dpr * hudK, 0, 0);
btnN = 0;
drawOverlayFx();
if (state === 'title') drawTitle();
else if (state === 'garage') drawGarage();
else if (state === 'playing') { if (net) netMarks(); else { drawMarker(); drawCursor(); } drawHUD(); if (paused) drawPaused(); if (net) netHUD(); }
else if (state === 'over') { if (net) netDrawOver(); else drawOver(); }
else if (state === 'online' || state === 'nsetup') netDraw();
