function onVisibility() { if (document.hidden) { if (!net) pauseGame(); clearHeld(); } }
function onContextMenu(e) { e.preventDefault(); }

function resize() {
if (destroyed) return;
const cw = Math.max(1, root.clientWidth), ch = Math.max(1, root.clientHeight);
viewW = cw; viewH = ch; dpr = window.devicePixelRatio || 1;
renderer.setSize(cw, ch, false);
camera.aspect = cw / ch;
camera.updateProjectionMatrix();
hud.width = Math.max(1, Math.round(cw * dpr)); hud.height = Math.max(1, Math.round(ch * dpr));
hudK = Math.min(cw / 960, ch / 600);
VW = cw / hudK; VH = ch / hudK;
makeGradients();
updatePointScale();
}
let lastT = performance.now(), lastFrame = lastT, frameAvg = 16, slowAcc = 0, fastAcc = 0;
function adaptRes(raw) {
if (!(raw > 0) || raw > 250) return;
frameAvg += (raw - frameAvg) * 0.08;
if (frameAvg > 20) {
fastAcc = 0; slowAcc += raw / 1000;
if (slowAcc > 1.5 && pixelRatio > 0.55) {
pixelRatio = Math.max(0.55, Math.round((pixelRatio - 0.15) * 100) / 100);
renderer.setPixelRatio(pixelRatio); renderer.setSize(viewW, viewH, false);
updatePointScale();
slowAcc = 0; frameAvg = 16;
}
} else if (frameAvg < 12) {
slowAcc = 0; fastAcc += raw / 1000;
if (fastAcc > 4 && pixelRatio < maxPR) {
pixelRatio = Math.min(maxPR, Math.round((pixelRatio + 0.1) * 100) / 100);
renderer.setPixelRatio(pixelRatio); renderer.setSize(viewW, viewH, false);
updatePointScale();
fastAcc = 0;
}
} else { slowAcc = 0; fastAcc = 0; }
}
function frame(now) {
if (destroyed) return;
raf = requestAnimationFrame(frame);
adaptRes(now - lastFrame);
lastFrame = now;
let dt = (now - lastT) / 1000;
lastT = now;
if (!(dt > 0)) dt = 0;
if (dt > 1 / 30) dt = 1 / 30;
if ((window.devicePixelRatio || 1) !== dpr) resize();
clock += dt;
const frozen = state === 'playing' && paused;
const live = state === 'playing' || state === 'over';
let sdt = frozen ? 0 : dt;
if (hitStop > 0 && !frozen) { hitStop -= dt; sdt = dt * 0.15; }
if (!frozen) {
if (state === 'playing' && NG) gstStep(dt);
else if (state === 'playing') {
applyInput(dt);
acc += sdt;
let n = 0;
while (acc >= STEP && n < MAX_STEPS) { simTruck(STEP); collideZombies(STEP); acc -= STEP; n++; }
if (n >= MAX_STEPS) acc = 0;
updateRun(sdt);
if (state === 'playing' && inp.thr > 0 && !T.dead && Math.abs(T.vF) < 1.5) {
stuckT += sdt;
if (stuckT > 2.5 && fx.hT <= 0) { fx.hText = touchMode ? 'Stuck? Let go of GAS and hold BRAKE to back up' : 'Stuck? Let go of W and hold S to back up'; fx.hT = 4; stuckT = 0; }
} else stuckT = 0;
if (state === 'playing') updateSpawns(sdt);
} else if (state === 'over') overT += dt;
if (live && !NG) {
updateZombies(sdt); updateClouds(sdt); updateBoss(sdt); updatePickups(sdt); updateDebris(sdt); updateTracers(sdt); scanNear();
streamWorld(T.z);
}
updateWeather(dt);
updatePS(psN, sdt); updatePS(psA, sdt);
if (fx.cT > 0) fx.cT -= dt;
if (fx.tT > 0) fx.tT -= dt;
if (fx.hT > 0) fx.hT -= dt;
if (toastT > 0) toastT -= dt;
if (dmgFlash > 0) dmgFlash = Math.max(0, dmgFlash - dt * 2.2);
}
const chh = chunkAt(T.z);
if (chh) palRegion = chh.region;
updateTruckVisual(frozen ? 0 : dt);
truckRoot.updateMatrixWorld(true);
if (state === 'playing') { if (net) netGuns(sdt); else updateGun(sdt, !frozen && inp.fire); }
else {
turretYaw.rotation.y = Math.sin(clock * 0.6) * 0.7; turretPitch.rotation.x = -0.12;
gun.hasTarget = false;
}
renderZombies();
if (net) netTick(dt);
updateCamera(frozen ? 0 : dt);
const tod = live && run ? todAt(run.dist) : 0.5;
updateAtmos(dt, tod);
updateAudio(dt);
renderer.render(scene, camera);
drawFrame();
}

const LISTENERS = [
[window, 'keydown', onKeyDown], [window, 'keyup', onKeyUp], [window, 'blur', onBlur],
[document, 'visibilitychange', onVisibility],
[hud, 'pointerdown', onPointerDown], [hud, 'pointermove', onPointerMove], [hud, 'pointerup', onPointerUp],
[hud, 'pointercancel', onPointerUp], [hud, 'contextmenu', onContextMenu],
];
let ro = null;
if (typeof ResizeObserver !== 'undefined') { ro = new ResizeObserver(function () { resize(); }); ro.observe(root); }
else LISTENERS.push([window, 'resize', resize]);
for (let i = 0; i < LISTENERS.length; i++) LISTENERS[i][0].addEventListener(LISTENERS[i][1], LISTENERS[i][2]);

const NET_OK = !!(api.net && api.net.supported && typeof api.net.open === 'function');
const NET_WHY = api.net && typeof api.net.open === 'function' ? 'Not available in this browser' : 'Needs a newer arcade';
