tx(i === 0 ? fmtInt(r.kills) : i === 1 ? r.combo + 'x' : i === 2 ? String(r.bosses) : mm + ':' + (ss < 10 ? '0' : '') + ss, c1 + cw, ly, 14, FONT_M, UI.head, 'right', cw * 0.4, 700);
const p = i < 3 ? netPl(i) : null;
