if (!Array.isArray(e)) continue;
const sp = Number(e[0]);
if (!(sp >= 0 && sp < NSP) || sp !== Math.floor(sp)) continue;
S.cooler.push({ sp: sp, w: num(e[1], SPECIES[sp].w0, 0.01, 1000), l: num(e[2], 20, 1, 1000), at: num(e[3], 0, 0, 3) | 0 });
