hemi.intensity = (0.28 + 0.5 * dayF) * dim + fl * 1.5;
skyU.uZen.value.copy(cZen); skyU.uHor.value.copy(cHor); skyU.uFogCol.value.copy(cFog);
skyU.uSunCol.value.copy(cSun).multiplyScalar(dayF * (1 - wv.cloud * 0.7));
