function shake(a) { if (!reduceMotion) { shakeAmp = Math.max(shakeAmp, a); shakeT = 0.35; } }
function setFs(s) { fs = s; fsT = 0; }
function docked() { const dx = boat.x - LOC.dockX, dz = boat.z - LOC.dockZ; return dx * dx + dz * dz < 15 * 15 && Math.abs(boat.v) < 3; }
function dockDist() { const dx = boat.x - LOC.dockX, dz = boat.z - LOC.dockZ; return Math.sqrt(dx * dx + dz * dz); }
