api.tone(220, 0.08, { type: 'square', vol: 0.1 }); api.tone(440, 0.12, { type: 'triangle', vol: 0.12, delay: 0.06 });
shake(0.15);
fishMesh.geometry = fishGeo(F.sp);
fishMat.emissive.setHex(s.ex.glow || 0);
