const reeling = actHeld();
F.reeling = reeling;
const inX = clamp((keys.KeyD ? 1 : 0) - (keys.KeyA ? 1 : 0) + touchRod, -1, 1);
rodX += (inX - rodX) * Math.min(1, dt * 6);
