let tot = 0;
for (let i = 0; i < S.cooler.length; i++) tot += priceOf(S.cooler[i].sp, S.cooler[i].w, S.loc);
const n = S.cooler.length;
S.cooler.length = 0;
S.money += tot; S.earned += tot; sess.earned += tot;
