const STICK = { id: -1, ox: 0, oy: 0, x: 0, y: 0 };
const STICK_R = 56;
const TB = { cx: 0, cy: 0, r: 62, lx: 0, rx: 0, ry: 0, rr: 30 };
function layoutTouch() { TB.cx = LW - 104; TB.cy = LH - 108; TB.lx = LW - 300; TB.rx = LW - 222; TB.ry = LH - 70; }
function drawTouch() {
if (!touchOn || mode !== 'playing' || menuOpen || paused) return;
layoutTouch();
const bx = STICK.id >= 0 ? STICK.ox : 110, by = STICK.id >= 0 ? STICK.oy : LH - 120;
ctx.fillStyle = 'rgba(255,255,255,0.08)'; ctx.beginPath(); ctx.arc(bx, by, STICK_R, 0, TAU); ctx.fill();
ctx.strokeStyle = 'rgba(255,255,255,0.25)'; ctx.lineWidth = 2; ctx.stroke();
ctx.fillStyle = 'rgba(255,255,255,0.35)';
ctx.beginPath(); ctx.arc(STICK.id >= 0 ? STICK.x : bx, STICK.id >= 0 ? STICK.y : by, 24, 0, TAU); ctx.fill();
const label = fs === 'idle' || fs === 'charge' ? 'CAST' : fs === 'bite' ? 'HOOK!' : fs === 'fight' ? 'REEL' : fs === 'landed' ? 'KEEP' : fs === 'wait' ? 'TWITCH' : '...';
ctx.fillStyle = touchAct ? UI.hi : fs === 'bite' ? 'rgba(255,201,60,0.7)' : 'rgba(255,201,60,0.28)';
ctx.beginPath(); ctx.arc(TB.cx, TB.cy, TB.r, 0, TAU); ctx.fill();
ctx.strokeStyle = '#fff1b8'; ctx.lineWidth = 2; ctx.stroke();
txt(ctx, label, TB.cx, TB.cy + 2, 18, FONT_D, touchAct || fs === 'bite' ? '#1a1406' : UI.head, 'center', TB.r * 1.7);
hit(TB.cx - TB.r, TB.cy - TB.r, TB.r * 2, TB.r * 2, 'tcast', 0);
const fighting = fs === 'fight';
for (let s = -1; s <= 1; s += 2) {
const x = s < 0 ? TB.lx : TB.rx, on = fighting && ((s < 0 && touchRod < 0) || (s > 0 && touchRod > 0));
ctx.fillStyle = on ? UI.hi : fighting ? 'rgba(255,255,255,0.22)' : 'rgba(255,255,255,0.08)';
ctx.beginPath(); ctx.arc(x, TB.ry, TB.rr, 0, TAU); ctx.fill();
poly(ctx, s < 0 ? [x - 10, TB.ry, x + 7, TB.ry - 11, x + 7, TB.ry + 11] : [x + 10, TB.ry, x - 7, TB.ry - 11, x - 7, TB.ry + 11], on ? '#1a1406' : UI.head);
hit(x - TB.rr - 4, TB.ry - TB.rr - 4, TB.rr * 2 + 8, TB.rr * 2 + 8, 'trod', s);
}
ctx.fillStyle = 'rgba(16,22,38,0.7)';
ctx.beginPath(); ctx.arc(LW - 36, 34, 22, 0, TAU); ctx.fill();
ctx.beginPath(); ctx.arc(LW - 92, 34, 22, 0, TAU); ctx.fill();
ctx.fillStyle = UI.head; ctx.fillRect(LW - 43, 25, 5, 18); ctx.fillRect(LW - 34, 25, 5, 18);
txt(ctx, 'BAG', LW - 92, 35, 11, FONT_D, UI.hi, 'center');
hit(LW - 60, 10, 48, 48, 'tpause', 0);
hit(LW - 116, 10, 48, 48, 'tmenu', 0);
}

