const deepK = smooth(0, 300, -P.y);
amb.deep.g.gain.setTargetAtTime(0.05 + 0.03 * deepK, t, 0.6);
amb.flow.g.gain.setTargetAtTime(0.004 + 0.03 * sf * sf, t, 0.4);
amb.flow.f.frequency.setTargetAtTime(380 + 500 * sf, t, 0.5);
amb.eng.frequency.setTargetAtTime(28 + 22 * sf + 4 * P.thr, t, 0.5);
amb.engF.frequency.setTargetAtTime(110 + 120 * sf, t, 0.5);
amb.engG.gain.setTargetAtTime(P.alive ? 0.008 + 0.018 * (P.thr / 3) : 0, t, 0.4);
