function drawHUD(now) {
const ctx = hctx;
ctx.setTransform(1, 0, 0, 1, 0, 0);
ctx.clearRect(0, 0, hud.width, hud.height);
const k = hudK * dpr;
ctx.setTransform(k, 0, 0, k, 0, 0);
btnN = 0;
if (state === 'title') drawTitle(ctx, now);
else if (state === 'menu') drawMenu(ctx, now);
else if (state === 'dock') drawDock(ctx, now);
else if (state === 'play') { drawPlay(ctx, now, false); if (paused) drawPause(ctx, now); }
else if (state === 'over') { drawPlay(ctx, now, true); drawOver(ctx, now); }
}

function setupMenuScene() {
clearEntities();
world.station = null; world.exit = null; world.intel = null;
const r = Math.min(2, Math.floor(nextMission() / 4));
buildWorld(r === 1 ? 'vents' : r === 2 ? 'abyss' : 'shelf', 31 + r, r);
P.st = stats(); setPlayerModel();
const sp = world.spawn;
P.x = sp.x; P.y = sp.y; P.z = sp.z; P.h = sp.h + 0.6; P.spd = 0; P.vy = 0; P.thr = 1; P.alive = true; P.pitch = 0; P.roll = 0;
P.hull = P.maxHull = P.st.hull; P.wired = null; P.sel = null;
wireView = false; mapOpen = false;
}
function toMenu() {
run = null; paused = false; ambStop();
setupMenuScene();
state = 'menu'; menuSel = MENU_ITEMS.indexOf(nextMission()); if (menuSel < 0) menuSel = 0;
clearHeld(); click(); snapCamera();
}
function toDock() { state = 'dock'; dockSel = save.cls; dockNoteT = 0; click(); }
function activateMenu() {
const it = MENU_ITEMS[clamp(menuSel, 0, MENU_ITEMS.length - 1)];
if (it === 'dock') { toDock(); return; }
if (it === 'free') { click(); beginRun(-1); return; }
if (!missionUnlocked(it)) { deny(); return; }
click(); beginRun(it);
}
function restartRun() {
if (run && run.done && !run.result) finishRun();
ambStop();
beginRun(run ? run.mi : nextMission());
}
function overContinue() { if (!overReady()) return; toMenu(); }
function overRetry() { if (!overReady() || !run) return; ambStop(); beginRun(run.mi); }
function pauseGame() {
if (state !== 'play' || paused || !run) return;
paused = true; pauseSel = 0;
ambStop(); clearHeld();
}
function resumeGame() {
if (!paused) return;
paused = false; acc = 0; lastT = performance.now(); ambPoll = 0;
clearHeld();
}
function pauseAction(i) {
if (i === 1) { paused = false; restartRun(); }
else if (i === 2) { paused = false; abandonRun(); }
else resumeGame();
}
