sun.position.set(-80, 34, 46);
scene.add(hemi); scene.add(sun);
const dummy = new THREE.Object3D();
const tmpV = new THREE.Vector3(), tmpC = new THREE.Color();
const ZERO_M = new THREE.Matrix4().makeScale(0, 0, 0);

const SKY_U = { uTop: { value: new THREE.Color(0x2a3f7a) }, uHor: { value: new THREE.Color(0xf0a070) }, uSun: { value: new THREE.Color(0xffd8a0) },
uSunDir: { value: new THREE.Vector3(-0.85, 0.3, 0.46).normalize() }, uGlow: { value: 0.55 } };
