const W = hud.width, H = hud.height;
if (PL.stormFx > 0.01) {
ctx.fillStyle = 'rgba(120, 60, 220, ' + (0.16 * PL.stormFx).toFixed(3) + ')'; ctx.fillRect(0, 0, W, H);
}
const low = P.alive && P.state === 'ground' && P.hp < 30 ? (0.25 + 0.2 * Math.sin(animT * 6)) : 0;
const a = Math.max(PL.flash * 0.55, low, PL.stormFx * 0.5);
