h.x = h.bx + Math.sin(animT * 0.13 + h.ph) * 3; h.y = h.by + Math.sin(animT * 0.31 + h.ph) * 0.8; h.z = h.bz + Math.cos(animT * 0.11 + h.ph) * 3;
a *= 0.5 + 0.5 * Math.sin(animT * 0.9 + h.ph);
