if (subHalo) { subHalo.x = POOL_X; subHalo.y = subGroup.position.y + 1.2; subHalo.z = POOL_Z + 0.3; subHalo.a = subReady ? 0.6 + 0.4 * Math.sin(t * 5) : launchT >= 0 ? 0.5 + 0.5 * Math.sin(t * 9) : 0.6; }
let want = 0;
