want = clamp(1 - d / 18, 0, 1) * (M.state === 'chase' || M.state === 'alert' ? 1 : M.state === 'investigate' || M.state === 'search' ? 0.75 : 0.5) + (M.state === 'chase' ? 0.3 : 0);
