w: 0, l: 0, pf: 0, pa: 0,
off: clamp((prev ? prev[i].off : t.off) + rand(-0.25, 0.32), 1.8, 4.8),
def: clamp((prev ? prev[i].def : t.def) + rand(-0.25, 0.32), 1.8, 4.8),
