const OFF = PL.slice(0, 7), DEF = PL.slice(7, 14);
const R = Object.create(null);
for (let i = 0; i < 7; i++) { R[OFF_ROLES[i]] = OFF[i]; R[DEF_ROLES[i]] = DEF[i]; }
const drawOrder = PL.slice();
const ball = { st: 'held', holder: null, x: 0, y: 0, h: 1, x0: 0, y0: 0, tx: 0, ty: 0, t: 0, T: 1, peak: 1, lob: false, target: null };
