function arrive() {
const out = ball.tx < 0 || ball.tx > FW || ball.ty > 110;
let o = null, od = 1.7;
for (let i = 0; i < 4; i++) {
const r = R[RECV[i]];
if (r.stun > 0) continue;
const dd = Math.hypot(r.x - ball.x, r.y - ball.y);
if (dd < od) { od = dd; o = r; }
}
let df = null, dfd = 99;
for (const d of DEF) {
if (d.stun > 0) continue;
const dd = Math.hypot(d.x - ball.x, d.y - ball.y);
if (dd < (d.diveT > 0 ? 1.6 : 1.35) && dd < dfd) { dfd = dd; df = d; }
}
if (df && (!o || dfd < od - 0.25)) {
if (!out && Math.random() < 0.3 + df.rat * 0.06 + (df.diveT > 0 ? 0.1 : 0)) intercept(df); else deflect(df);
return;
}
if (o && !out) {
const pc = 0.66 + o.rat * 0.06 - (df ? 0.25 : 0) - (ball.lob ? 0.02 : 0);
if (Math.random() < pc) { catchBall(o); return; }
pop(o.x, o.y + 2.5, 'DROPPED', PAL.bad);
}
dust(ball.x, ball.y, 6);
tone(180, 0.06, { type: 'triangle', vol: 0.05 });
endPlay('inc', M.los);
}
function catchBall(o) {
ball.st = 'held'; ball.holder = o; ball.h = 1; M.passOK = false;
if (M.poss === 0) { M.ctrl = o; M.manual = false; }
pop(o.x, o.y + 2.5, 'CATCH!', M.poss === 0 ? PAL.ok : PAL.text);
tone(660, 0.05, { type: 'square', vol: 0.05 }); tone(990, 0.08, { type: 'square', vol: 0.05, delay: 0.05 });
}
