if (ball.st === 'air') stepBall(h);
else if (ball.st === 'held' && ball.holder) { ball.x = ball.holder.x; ball.y = ball.holder.y; }
if (M.phase !== 'live') return;
checkCarrier();
if (M.phase !== 'live') return;
