function drawGame() {
const userOff = M.poss === 0;
const offT = TEAMS[userOff ? M.ut : M.opp], defT = TEAMS[userOff ? M.opp : M.ut];
camR = M.camY;
const ph = M.phase;
g.save();
if (shake > 0 && !paused) g.translate(Math.round((Math.random() * 2 - 1) * shake), Math.round((Math.random() * 2 - 1) * shake));
drawField(offT, defT, ph !== 'kickfly' && ph !== 'kick');
drawPosts(110); drawPosts(-10);
if (userOff && (ph === 'pre' || (ph === 'live' && M.routeT > 0))) drawRoutes(ph === 'pre' ? 0.5 : 0.5 * M.routeT);
drawPlayers();
drawBallFree();
drawFx();
drawAim();
g.restore();
drawHUD();
const c = holderNow();
if (ph === 'call') drawCallPanel();
else if (ph === 'fourth') drawFourth();
else if (ph === 'pat') drawChoice('TOUCHDOWN! NOW...', PAT_OPTS, -1);
else if (ph === 'kick') drawMeter();
else if (ph === 'pre') {
ptext(g, (userOff ? 'PLAY: ' + PLAYS[M.play].key : 'DEFENSE: ' + SCHEMES[M.scheme].key), 6, 15, PAL.hi, 'left', 1, true);
if (userOff) {
drawHint(ptrMode ? 'TAP FIELD TO SNAP' : 'SPACE: SNAP    1-6: CHANGE PLAY');
pbox(g, LW - 52, LH - 26, 48, 13, PAL.panel2, PAL.hi);
ptext(g, 'PLAYS', LW - 28, LH - 23, '#ffffff', 'center');
addBtn(LW - 54, LH - 28, 52, 17, 'change', 0);
} else drawHint(ptrMode ? 'TAP TO SNAP - YOU ARE THE ARROW' : 'SPACE: SNAP NOW - YOU ARE THE ARROW');
} else if (ph === 'live') {
const qbHold = userOff && c === R.qb && M.passOK;
if (qbHold) { if (M.plays <= 8 || ptrMode) drawHint(ptrMode ? 'DRAG BACK TO THROW - LONG DRAG = LOB' : 'DRAG BACK TO THROW   1-4 PASS   SHIFT+# LOB'); }
else if (userOff && c === M.ctrl && c && M.plays <= 8 && !ptrMode) drawHint('ARROWS STEER   SPACE JUKE   SHIFT DIVE');
else if (!userOff && M.plays <= 8 && !ptrMode) drawHint('ARROWS MOVE   SPACE DIVE / TACKLE');
if (ptrMode && M.ctrl && !qbHold && (!userOff || c === M.ctrl)) drawStick(userOff);
else if (ptrMode && qbHold && joy.on) drawStick(true);
} else if (ph === 'dead' && M.msg) {
const t = M.deadMax - M.deadT, a = Math.min(1, t / 0.18), y = 60;
const sub = !!M.msgSub;
g.fillStyle = 'rgba(8, 12, 22, 0.8)'; g.fillRect(0, y - 6, LW, sub ? 34 : 26);
g.fillStyle = M.msgCol; g.fillRect(0, y - 6, LW, 1); g.fillRect(0, y + (sub ? 27 : 19), LW, 1);
const sc = textW(M.msg, 2) > LW - 16 ? 1 : 2;
ptext(g, M.msg, LW / 2 + Math.round((1 - easeOutCubic(a)) * 50), y + (sc === 1 ? 4 : 0), M.msgCol, 'center', sc, true);
if (sub) ptext(g, M.msgSub, LW / 2, y + 18, PAL.text, 'center', 1, true);
}
}

const POS_TIP = ['ACCURACY + ARM', 'SPEED + POWER', 'SPEED + HANDS', 'SPEED + HANDS', 'HANDS + BLOCKING',
'POCKET TIME, BOTH LINES', 'YOUR DEFENDER + COVERAGE', 'METER SIZE + RANGE'];
const HUB_ITEMS = ['', 'ROSTER & TRAINING', 'STANDINGS', 'SAVE & QUIT'];

function go(name) {
mode = 'playing'; screen = name; sel = 0; paused = false; standCache = null; screenAt = performance.now();
aim.on = false; joy.on = false;
}
function menuReady() { return performance.now() - screenAt >= 450; }
function menuCount() {
switch (screen) {
case 'teams': return TEAMS.length + 1;
case 'hub': return 4;
case 'roster': return 9;
case 'offseason': return 4;
case 'standings': case 'post': return 1;
default: return 0;
}
}
function activate(n) {
tone(523, 0.05, { type: 'square', vol: 0.045 });
if (screen === 'teams') {
if (n >= TEAMS.length) { mode = 'title'; return; }
if (teamsFor === 'quick') startQuick(n); else newFranchise(n);
} else if (!fr && screen !== 'post') {
mode = 'title';
} else if (screen === 'hub') {
if (n === 0) playWeek();
else if (n === 1) go('roster');
else if (n === 2) go('standings');
else { writeSave(); mode = 'title'; titleSel = 0; }
} else if (screen === 'roster') {
if (n >= 8) go('hub'); else train(n);
} else if (screen === 'standings') {
go('hub'); sel = 2;
} else if (screen === 'post') {
if (!post || post.quick) { quick = false; mode = 'title'; titleSel = 0; return; }
if (post.over) { mode = 'over'; overAt = performance.now(); return; }
go('hub');
} else if (screen === 'offseason') signRookie(n < 3 ? n : -1);
}
function navKey(c) {
if (mode !== 'playing' || paused) return false;
const up = c === 'ArrowUp' || c === 'KeyW', down = c === 'ArrowDown' || c === 'KeyS';
const left = c === 'ArrowLeft' || c === 'KeyA', right = c === 'ArrowRight' || c === 'KeyD';
if (screen === 'game') {
const n = optionCount();
if (!n) return false;
const cols = M.phase === 'call' ? (M.poss === 0 ? 3 : 2) : 1;
let s = M.sel;
if (left) s -= 1; else if (right) s += 1; else if (up) s -= cols; else if (down) s += cols;
M.sel = clamp(s, 0, n - 1);
tone(440, 0.03, { type: 'square', vol: 0.03 });
return true;
}
const n = menuCount();
if (!n) return false;
if (screen === 'teams') {
if (sel >= 12) { if (up) sel = 8; }
else if (left) sel = Math.max(0, sel - 1);
else if (right) sel = Math.min(11, sel + 1);
else if (up) sel = sel >= 4 ? sel - 4 : sel;
else if (down) sel = sel + 4 < 12 ? sel + 4 : 12;
} else if (up || left) sel = (sel + n - 1) % n;
else if (down || right) sel = (sel + 1) % n;
tone(440, 0.03, { type: 'square', vol: 0.03 });
return true;
}

