function otext(s, x, y, size, family, color, align, maxW, weight) {
ctx.font = (weight ? weight + ' ' : '') + size + 'px ' + family;
if (maxW) {
const w = ctx.measureText(s).width;
if (w > maxW) { size = Math.max(8, Math.floor(size * maxW / w)); ctx.font = (weight ? weight + ' ' : '') + size + 'px ' + family; }
}
ctx.fillStyle = color; ctx.textAlign = align || 'center'; ctx.textBaseline = 'middle';
ctx.fillText(s, x, y);
}
function opanel(x, y, w, h, stroke) {
const r = 18;
ctx.beginPath();
ctx.moveTo(x + r, y);
ctx.arcTo(x + w, y, x + w, y + h, r); ctx.arcTo(x + w, y + h, x, y + h, r);
ctx.arcTo(x, y + h, x, y, r); ctx.arcTo(x, y, x + w, y, r);
ctx.closePath();
ctx.fillStyle = UI.panel; ctx.fill();
ctx.lineWidth = 2; ctx.strokeStyle = stroke || UI.stroke; ctx.stroke();
}
