addPop({ x: clamp(x, BX + 40, BX + BW - 40), y: y - 24, text: cr.sp === SP_PRISM ? 'Prism!' : cr.sp === SP_BURST ? 'Burst!' : 'Bolt!', color: C_HI, size: 16, font: FD, w: '', life: 0, max: 0.8 });
