if (g.mag >= magMax(g) || g.res <= 0) return;
const d = WEAPONS[g.w];
P.reloadDur = d.reload * (P.perks.quick ? 0.55 : 1) * (d.shell ? 1 : 1);
P.reloadT = P.reloadDur;
P.sprint = false;
