let cand = -1, seen = 0;
for (let pass = 0; pass < 2 && cand < 0; pass++) {
const lo = pass === 0 ? 8 : 4, hi = pass === 0 ? 18 : 40;
seen = 0;
for (let i = 0; i < N; i++) {
const v = flow[i];
if (v < lo || v > hi) continue;
seen++;
if (Math.random() * seen < 1) cand = i;
}
}
if (cand < 0) return false;
