let a = null;
try { a = api.audio ? api.audio() : null; } catch (err) { a = null; }
if (!a || !a.ctx || !a.out) return;
const ac = a.ctx;
amb = { ctx: ac, nodes: [], droneG: null, droneF: null, humG: null };
const nodes = amb.nodes;
