const bobOn = reduceMotion ? 0 : (P.onGround ? Math.min(1, Math.hypot(P.vx, P.vz) / WALK) : 0);
let cx = P.x + ax.rx * Math.cos(P.bob) * 0.03 * bobOn, cz = P.z + ax.rz * Math.cos(P.bob) * 0.03 * bobOn;
let cy = P.y + EYE - P.land + Math.sin(P.bob * 2) * 0.04 * bobOn, pitch = P.pitch, roll = 0;
