if (e.repeat) return;
if (c === 'KeyF' || c === 'KeyJ') aimAssist = aimAssist || !isLocked();
else if (c === 'KeyP' || c === 'Escape') pause();
else if (c === 'Space') jumpBuf = 0.15;
else if (c === 'KeyR') startReload();
else if (c === 'Digit1') switchWeapon(0);
else if (c === 'Digit2') switchWeapon(1);
else if (c === 'Digit3') switchWeapon(2);
else if (c === 'KeyQ') switchWeapon((wi + 1) % 3);
