function rnd(){return Math.random();}
function rs(){return Math.random()-0.5;} // random in -0.5 .. 0.5
function clamp(v,a,b){return v<a?a:(v>b?b:v);}
function lerp(a,b,t){return a+(b-a)*t;}
function wrapA(a){if(!isFinite(a))return 0;a=(a+Math.PI)%TAU;if(a<0)a+=TAU;return a-Math.PI;}
function seeded(seed){
let a=seed>>>0;
return function(){a=(a+0x6D2B79F5)>>>0;let t=a;t=Math.imul(t^(t>>>15),t|1);t^=t+Math.imul(t^(t>>>7),t|61);return((t^(t>>>14))>>>0)/4294967296;};
}
function rr(g,x,y,w,h,r){
const q=Math.max(0,Math.min(r,w/2,h/2));
g.beginPath();g.moveTo(x+q,y);g.arcTo(x+w,y,x+w,y+h,q);g.arcTo(x+w,y+h,x,y+h,q);
g.arcTo(x,y+h,x,y,q);g.arcTo(x,y,x+w,y,q);g.closePath();
}
function fmt(n) { return String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, ','); }
function css(hex,k){
const m=k==null?1:k;
const r=Math.min(255,Math.round(((hex>>16)&255)*m)),g=Math.min(255,Math.round(((hex>>8)&255)*m)),b=Math.min(255,Math.round((hex&255)*m));
return 'rgb('+r+','+g+','+b+')';
}

function poly(g,pts,fill){g.fillStyle=fill;g.beginPath();g.moveTo(pts[0],pts[1]);for(let i=2;i<pts.length;i+=2)g.lineTo(pts[i],pts[i+1]);g.closePath();g.fill();}
