const flashIM=makeIM(keep(new THREE.IcosahedronGeometry(1,1)),matGlow,26);
const FL=[];for(let i=0;i<26;i++)FL.push({t:0,max:1,x:0,y:0,z:0,s0:1,s1:2,r:1,g:1,b:1});
const ringGeo=keep(new THREE.RingGeometry(0.82,1,40));ringGeo.rotateX(-Math.PI/2);
const ringIM=makeIM(ringGeo,matGlow,24); // 0..13 shock rings, 14..21 artillery marks, 22 mortar aim, 23 spare
const RG=[];for(let i=0;i<14;i++)RG.push({t:0,max:1,x:0,y:0,z:0,r0:1,r1:8,r:1,g:1,b:1});
const beamIM=makeIM(unitZ,matGlow,28);
const BM=[];for(let i=0;i<28;i++)BM.push({t:0,max:1,x0:0,y0:0,z0:0,x1:0,y1:0,z1:0,w:0.2,r:1,g:1,b:1});
const debGeo=keep(prep(new THREE.BoxGeometry(1,1,1),0xffffff));
const DEB_CAP=220;
const debIM=makeIM(debGeo,matIM,DEB_CAP);
const DB={n:0,live:new Uint8Array(DEB_CAP),x:new Float32Array(DEB_CAP),y:new Float32Array(DEB_CAP),z:new Float32Array(DEB_CAP),
vx:new Float32Array(DEB_CAP),vy:new Float32Array(DEB_CAP),vz:new Float32Array(DEB_CAP),rx:new Float32Array(DEB_CAP),ry:new Float32Array(DEB_CAP),
wx:new Float32Array(DEB_CAP),wy:new Float32Array(DEB_CAP),sx:new Float32Array(DEB_CAP),sy:new Float32Array(DEB_CAP),sz:new Float32Array(DEB_CAP),
life:new Float32Array(DEB_CAP),smoke:new Uint8Array(DEB_CAP),next:0};
const scorchGeo=keep(new THREE.PlaneGeometry(1,1));scorchGeo.rotateX(-Math.PI/2);
const scorchIM=makeIM(scorchGeo,matScorch,48);
let scorchNext=0;
const blobIM=makeIM(scorchGeo,matBlob,56);
let blobN=0,blobLast=0;
const markGeo=keep(new THREE.RingGeometry(0.9,1,48));markGeo.rotateX(-Math.PI/2);
const zoneMesh=new THREE.Mesh(markGeo,keep(new THREE.MeshBasicMaterial({color:0x4be3a0,transparent:true,opacity:0.7,blending:THREE.AdditiveBlending,depthWrite:false,side:THREE.DoubleSide,fog:false})));
zoneMesh.visible=false;scene.add(zoneMesh);
const zoneFill=new THREE.Mesh(keep(new THREE.CircleGeometry(1,40)),keep(new THREE.MeshBasicMaterial({color:0x4be3a0,transparent:true,opacity:0.12,blending:THREE.AdditiveBlending,depthWrite:false,fog:false})));
