const snowGeo=keep(new THREE.BufferGeometry());snowGeo.setAttribute('position',new THREE.BufferAttribute(snowPos,3));
const snow=new THREE.Points(snowGeo,keep(new THREE.PointsMaterial({color:0xe8f0ff,size:0.35,transparent:true,opacity:0.8,depthWrite:false})));
