function makeRig(parent){
const mat=keep(new THREE.MeshLambertMaterial({vertexColors:true,emissive:0x000000}));
const G=function(){return new THREE.Group();},M=function(){return new THREE.Mesh(emptyGeo,mat);};
const R={mat:mat,set:null,root:G(),hip:G(),legL:G(),legR:G(),kneeL:G(),kneeR:G(),torsoP:G(),armLP:G(),armRP:G(),
pelvis:M(),thighL:M(),thighR:M(),shinL:M(),shinR:M(),torso:M(),armL:M(),armR:M()};
R.root.add(R.hip);R.hip.add(R.pelvis);R.hip.add(R.legL);R.hip.add(R.legR);R.hip.add(R.torsoP);
R.legL.add(R.thighL);R.legL.add(R.kneeL);R.kneeL.add(R.shinL);
R.legR.add(R.thighR);R.legR.add(R.kneeR);R.kneeR.add(R.shinR);
R.torsoP.add(R.torso);R.torsoP.add(R.armLP);R.torsoP.add(R.armRP);R.armLP.add(R.armL);R.armRP.add(R.armR);
R.root.visible=false;parent.add(R.root);
return R;
}
function setRig(R,set){
R.set=set;const D=set.dims;
R.pelvis.geometry=set.pelvis;R.thighL.geometry=set.thigh;R.thighR.geometry=set.thigh;R.shinL.geometry=set.shin;R.shinR.geometry=set.shin;
R.torso.geometry=set.torso;R.armL.geometry=set.armL;R.armR.geometry=set.armR;
R.legL.position.set(D.hipX,0,0);R.legR.position.set(-D.hipX,0,0);
R.kneeL.position.set(0,-D.thigh,0);R.kneeR.position.set(0,-D.thigh,0);
R.torsoP.position.set(0,0.45,0);R.armLP.position.set(D.armX,D.armY,0);R.armRP.position.set(-D.armX,D.armY,0);
R.armL.visible=true;R.armR.visible=true;R.torso.visible=true;
R.hip.position.set(0,D.hipY,0);
}
function poseRig(R,u){
const D=R.set.dims;
R.root.position.set(u.x,u.y,u.z);R.root.rotation.y=u.legYaw;
const amp=u.air?0:u.walk*0.5,ph=u.legPh,s=Math.sin(ph),c=Math.cos(ph);
let tL=D.rT+amp*s,tR=D.rT-amp*s;
let kL=D.rK+D.kSign*amp*1.1*Math.max(0,-c),kR=D.rK+D.kSign*amp*1.1*Math.max(0,c);
if(u.air){tL=tR=D.rT-0.3*D.kSign;kL=kR=D.rK+0.55*D.kSign;}
R.legL.rotation.x=tL;R.legR.rotation.x=tR;R.kneeL.rotation.x=kL;R.kneeR.rotation.x=kR;
const drop=(D.thigh+D.shin)*(1-Math.cos(amp*Math.abs(s)))+u.crouch;
R.hip.position.y=D.hipY-drop;u.hipH=D.hipY-drop;
R.torsoP.rotation.set(u.slump,wrapA(u.visYaw-u.legYaw),amp*0.05*s,'YXZ');
R.armLP.rotation.x= -u.pitch+u.recoilL;R.armRP.rotation.x= -u.pitch+u.recoilR;
}
