inert:false,flash:0,cd:0,cd2:0,cd3:0,burst:0,burstT:0,state:0,t:0,tgt:null,alt:0,orbit:1,strafe:1,strafeT:0,
stuckT:0,lastX:0,lastZ:0,sideT:0,sideYaw:0,stuckN:0,losT:0,los:false,legPh:0,walk:0,spd:0,smokeT:0,dmgMul:1,avoid:1,
rig:null,cls:'',legYaw:0,aimYaw:0,visYaw:0,pitch:0,air:false,crouch:0,slump:0,hipH:0,recoilL:0,recoilR:0,scale:1,
