u.rig=null;u.air=false;u.crouch=0;u.slump=0;u.recoilL=0;u.recoilR=0;u.scale=1;u.armOK[0]=true;u.armOK[1]=true;u.jumpT=3+rnd()*4;
u.lockU=null;u.flaming=false;u.trig1=false;u.trig2=false;u.boss=null;u.shielded=false;u.armor=false;u.respawn=0;u.mark= -1;u.slot= -1;
u.avoid=rnd()<0.5?1: -1;u.orbit=rnd()<0.5?1: -1;u.strafe=u.orbit;u.strafeT=2;u.aimErrT=0;u.pitch=0;u.alt=0;
for(let k=0;k<4;k++){const w=u.ws[k];w.wi=0;w.ammo=0;w.max=0;w.cd=0;w.charge=0;w.charging=false;w.burst=0;w.flameT=0;}
