const vx=SH.vx[i],vy=SH.vy[i],vz=SH.vz[i],sp=Math.sqrt(vx*vx+vy*vy+vz*vz)||1,dx=vx/sp,dy=vy/sp,dz=vz/sp,L=sp*dt;
