u.spd=sp;
const vx=Math.sin(u.yaw)*sp,vz=Math.cos(u.yaw)*sp;
u.x+=vx*dt;u.z+=vz*dt;u.vx=vx;u.vz=vz;
pushOut(u,u.r);
