let vx=gx-u.x,vz=gz-u.z;const vl=Math.sqrt(vx*vx+vz*vz)||1,s2=Math.min(sp,vl*1.5);
vx=vx/vl*s2;vz=vz/vl*s2;
u.vx+=(vx-u.vx)*Math.min(1,dt*1.5);u.vz+=(vz-u.vz)*Math.min(1,dt*1.5);
