if(u.inert)holdStill(u);
else if(!engaged){const w=M.cmdrPath[M.cmdrWP%M.cmdrPath.length];if(Math.hypot(w[0]-u.x,w[1]-u.z)<6)M.cmdrWP++;steer(u,w[0],w[1],speed*0.6,dt,L.turn);}
else if(d>E.range+10|| !u.los)steer(u,t.x,t.z,speed,dt,L.turn*1.1);
else if(d<E.range-12)steer(u,u.x-dx/d*12,u.z-dz/d*12,speed*0.7,dt,L.turn*1.1);
else steer(u,u.x-dz/d*10*u.strafe,u.z+dx/d*10*u.strafe,speed*0.6,dt,L.turn*1.1);
u.legYaw=u.yaw;
