function sepSkip(u){return!u.act||u.cat==='bpart'||(u.cat==='en'&&u.type==='gunship');}
function sepFix(u){return u.cat==='haul'||u.cat==='obj'||(u.cat==='en'&&(u.type==='arty'||u.type==='turret'));}
function separate(){
for(let i=0;i<U_CAP;i++){
const a=U[i];
if(sepSkip(a))continue;
const aFix=sepFix(a);
for(let j=i+1;j<U_CAP;j++){
const b=U[j];
if(sepSkip(b))continue;
const bFix=sepFix(b);
if(aFix&&bFix)continue;
if(aFix?b.y>a.y+a.h-0.5:bFix?a.y>b.y+b.h-0.5:Math.abs(a.y-b.y)>4)continue;
const dx=b.x-a.x,dz=b.z-a.z,rr=a.r+b.r,d2=dx*dx+dz*dz;
if(d2>=rr*rr||d2<1e-6)continue;
const d=Math.sqrt(d2),push=(rr-d)*0.5,nx=dx/d,nz=dz/d;
if(!aFix){a.x-=nx*push*(bFix?2:1);a.z-=nz*push*(bFix?2:1);}
if(!bFix){b.x+=nx*push*(aFix?2:1);b.z+=nz*push*(aFix?2:1);}
}
}
}

