ctx.fillStyle='rgba(0, 0, 0, 0.35)';ctx.fillRect(bx-12,by+8,24,5);
ctx.fillStyle=secCol(f[2]);rr(ctx,bx+26,by+4,16,38,5);ctx.fill();
ctx.fillStyle=secCol(f[3]);rr(ctx,bx-42,by+4,16,38,5);ctx.fill();
