const LAB_ROWS=['bay','legs','torso','arms','sh','w0','w1','w2','w3','p','s','v','d','dc'];
const LAB_NAMES={bay:'DESIGN BAY',legs:'LEGS',torso:'TORSO',arms:'ARMS',sh:'SHOULDERS',w0:'L ARM',w1:'R ARM',w2:'L SHOULDER',w3:'R SHOULDER',p:'PAINT',s:'TRIM',v:'VISOR',d:'DECAL',dc:'DECAL COLOUR'};
const WCH={1:[],2:[]};
for(let i=0;i<WEAPONS.length;i++){if(WEAPONS[i].mount&1)WCH[1].push(i);if(WEAPONS[i].mount&2)WCH[2].push(i);}
let labMsg='',labMsgT=0,labMsgCol=C_OK,labSaved=null,labSpin=0,labDrag=null;
function labSay(s,col){labMsg=s;labMsgCol=col||C_OK;labMsgT=2.6;}
function openLab(){screen='lab';uiFocus='legs';labSaved=JSON.parse(JSON.stringify(curDesign()));buildPlayerSet();}
function partKey(id){return id==='legs'||id==='torso'||id==='arms'||id==='sh'?id:null;}
function rowOwned(id){
const d=curDesign(),pk=partKey(id);
if(pk)return prof.own[pk][d[pk]];
if(id.charAt(0)==='w')return prof.own.w[d.w[+id.charAt(1)]];
return true;
}
function rowCost(id){
const d=curDesign(),pk=partKey(id);
if(pk)return partList(pk)[d[pk]].cost;
if(id.charAt(0)==='w')return WEAPONS[d.w[+id.charAt(1)]].cost;
return 0;
}
function rowValue(id){
const d=curDesign();
switch(id){
case 'bay':return 'Bay '+(prof.active+1)+' of 3';
case 'legs':return LEGS[d.legs].name;case 'torso':return TORSOS[d.torso].name;case 'arms':return ARMS[d.arms].name;case 'sh':return SHOULDERS[d.sh].name;
case 'p':return PAINT_P[d.p][0];case 's':return PAINT_S[d.s][0];case 'v':return VISORS[d.v][0];case 'd':return DECALS[d.d];case 'dc':return PAINT_S[d.dc][0];
default:return WEAPONS[d.w[+id.charAt(1)]].name;
}
}
function rowInfo(id){
const d=curDesign();
switch(id){
case 'bay':return 'Three saved designs. The selected bay is the mech you deploy.';
case 'legs':{const L=LEGS[d.legs];return L.cls+' legs: speed '+L.speed+', armour '+L.arm+', carry '+L.cap+' t, jets '+L.fuel+' s. Weight '+L.wt+' t.';}
case 'torso':{const T=TORSOS[d.torso];return 'Armour '+T.arm+', cooling '+T.sink+'/s, power '+T.power+'. Weight '+T.wt+' t.';}
case 'arms':{const A=ARMS[d.arms];return 'Arm armour '+A.arm+' each. Weight '+A.wt+' t.';}
case 'sh':{const S=SHOULDERS[d.sh];return(S.armB?'+'+S.armB+' arm armour. ':'')+(S.ammoB>1?'+'+Math.round((S.ammoB-1)*100)+'% shoulder ammo. ':'')+'Weight '+S.wt+' t.';}
case 'w0':case 'w1':case 'w2':case 'w3':{
const W=WEAPONS[d.w[+id.charAt(1)]];
if(!W.wt)return 'Empty hardpoint. Enter: switch fire group.';
const tips={'AUTOCANNON':'Rapid tracers. Hold to fire.','PULSE LASER':'Instant 3-pulse burst, no ammo.','MISSILES':'Six missiles; they lock on to the target under your crosshair.','FLAK GUN':'Close-range shotgun; great against gunships.','FLAMER':'Short-range fire cone. Runs hot.','RAILGUN':'Charges, then pierces every machine in line. Tap to auto-charge.','PLASMA MORTAR':'Lobbed plasma with a huge blast. Shows a landing ring.'};
return tips[W.short]+' '+W.wt+' t, '+W.pw+' power'+(W.ammo?', '+W.ammo+' rounds':', energy')+'. Enter: switch group.';
}
default:return 'Paint and decals are free. Change them as often as you like.';
}
}
function labRebuild(){
buildPlayerSet();
const d=curDesign(),B=budget(d);
if(B.owned&&B.ok){labSaved=JSON.parse(JSON.stringify(d));saveProfile();} // labSaved is always the last design that could deploy
}
function labAdjust(id,dir){
const d=curDesign(),pk=partKey(id);
if(id==='bay'){leaveLabFix();prof.active=(prof.active+dir+3)%3;labSaved=JSON.parse(JSON.stringify(curDesign()));buildPlayerSet();saveProfile();sfx('select');return;}
if(pk){const n=partList(pk).length;d[pk]=(d[pk]+dir+n)%n;}
else if(id.charAt(0)==='w'){const k= +id.charAt(1),list=WCH[HP_MOUNT[k]],i=list.indexOf(d.w[k]);d.w[k]=list[(i+dir+list.length)%list.length];}
else if(id==='p')d.p=(d.p+dir+PAINT_P.length)%PAINT_P.length;
else if(id==='s')d.s=(d.s+dir+PAINT_S.length)%PAINT_S.length;
else if(id==='v')d.v=(d.v+dir+VISORS.length)%VISORS.length;
else if(id==='d')d.d=(d.d+dir+DECALS.length)%DECALS.length;
else if(id==='dc')d.dc=(d.dc+dir+PAINT_S.length)%PAINT_S.length;
else return;
sfx('select');labRebuild();
}
function labActivate(id){
const d=curDesign();
if(id==='test'){if(!labReady())return;startMission(TEST);return;}
if(id==='done'){leaveLab();return;}
if(id.charAt(0)==='g'){const k= +id.charAt(1);d.g[k]=d.g[k]===1?2:1;sfx('select');labRebuild();return;}
if(LAB_ROWS.indexOf(id)<0)return;
if(!rowOwned(id)){
const c=rowCost(id),pk=partKey(id);
if(prof.salv<c){labSay('Need '+fmt(c)+' salvage (you have '+fmt(prof.salv)+'). Earn more in missions.',C_BAD);sfx('deny');return;}
prof.salv-=c;
if(pk)prof.own[pk][d[pk]]=true;else prof.own.w[d.w[+id.charAt(1)]]=true;
labSay('Unlocked '+rowValue(id)+'!',C_OK);sfx('buy');labRebuild();return;
}
if(id.charAt(0)==='w'){const k= +id.charAt(1);d.g[k]=d.g[k]===1?2:1;labSay(HP_NAME[k]+' now fires with group '+d.g[k],C_HI);sfx('select');labRebuild();return;}
labAdjust(id,1);
}
function labReady(){
const B=budget(curDesign());
if(!B.owned){labSay('A selected part is locked: buy it (Enter) or pick another.',C_BAD);sfx('deny');return false;}
if(B.wt>B.cap){labSay('Over the weight limit: lighter parts or heavier legs.',C_BAD);sfx('deny');return false;}
if(B.pw>B.power){labSay('Not enough power: fewer energy weapons or a stronger torso.',C_BAD);sfx('deny');return false;}
return true;
}
function leaveLabFix(){
const d=curDesign(),s=labSaved&&ownsDesign(labSaved)?labSaved:defDesign();
if(!prof.own.legs[d.legs])d.legs=s.legs;
if(!prof.own.torso[d.torso])d.torso=s.torso;
if(!prof.own.arms[d.arms])d.arms=s.arms;
if(!prof.own.sh[d.sh])d.sh=s.sh;
for(let k=0;k<4;k++)if(!prof.own.w[d.w[k]])d.w[k]=s.w[k];
if(!budget(d).ok){const f=s&&budget(s).ok?s:defDesign();prof.designs[prof.active]=JSON.parse(JSON.stringify(f));return 'Over budget: restored your last working design.';}
return '';
}
function leaveLab(){
const msg=leaveLabFix();
buildPlayerSet();saveProfile();
screen='menu';uiFocus='lab';
if(msg){menuMsg=msg;menuMsgT=3;}
sfx('ui');
}
function ensureDesign(){leaveLabFix();if(!ownsDesign(curDesign())|| !budget(curDesign()).ok)prof.designs[prof.active]=defDesign();}
