playerStep(dt);
for(let i=1;i<U_CAP;i++){const u=U[i];if(!u.act)continue;if(u.cat==='en')enemyStep(u,dt);else if(u.cat==='mech')mechAI(u,dt);}
bossStep(dt);
separate();
director(dt);
updBullets(dt);updMissiles(dt);updShells(dt);updBooms(dt);
