for(let i=0;i<SNOW_N;i++){p[i*3+1]-=dt*(5+(i%5));p[i*3]+=dt*1.5;if(p[i*3+1]<0){p[i*3+1]+=60;p[i*3]=rs()*120;}if(p[i*3]>60)p[i*3]-=120;}
