labU.x=0;labU.y=0.25;labU.z=0;labU.legYaw=labSpin+animT*(screen==='lab'?0.3:0.18)-0.6;labU.visYaw=labU.legYaw+Math.sin(animT*0.6)*0.35;
labU.pitch=Math.sin(animT*0.45)*0.12;labU.walk=0;labU.air=false;labU.crouch=0;labU.slump=0;labU.recoilL=0;labU.recoilR=0;labU.legPh=0;
labRig.root.visible= !!labRig.set;
