SH.vx[i] = rand(-1, 1) * (3 + spread * 3); SH.vy[i] = rand(2, 6 + spread * 2); SH.vz[i] = rand(-1, 1) * (3 + spread * 3);
SH.rx[i] = rand(0, TAU); SH.ry[i] = rand(0, TAU); SH.spin[i] = rand(-12, 12);
SH.life[i] = SH.max[i] = rand(0.6, 1.1); SH.s[i] = rand(0.12, 0.26) * (0.7 + spread * 0.6);
