CH.vx[i] = rand(-5, 5); CH.vy[i] = rand(3, 8); CH.vz[i] = rand(-5, 5);
CH.rx[i] = rand(0, TAU); CH.ry[i] = rand(0, TAU); CH.spin[i] = rand(-10, 10);
