flowJob = false; heapN = 0; flowDirty = false;
P.alive = false; P.active = false; P.gatherNode = -1; P.dashT = 0; P.downT = 0; P.invT = 0; P.reloadT = 0;
queenPending = false; spawnTotal = 0; spawnedSoFar = 0; vacuum = false;
