phase = 'dawn'; dawnT = 3.2; vacuum = true;
exitBuild();
const bs = 20 + 8 * nightsSurvived, bc = 10 + 5 * nightsSurvived;
scrap += bs; crys += bc;
for (let i = 0; i < nodes.length; i++) { const N = nodes[i]; N.res = Math.min(N.max, N.res + N.max * 0.6); N.acc = 0; }
for (let s = 0; s < bldHigh; s++) { const B = blds[s]; if (B.alive) B.hp = Math.min(B.maxHp, B.hp + B.maxHp * 0.25); }
