if (inRect(q.x, q.y, BTN_CONT.x, BTN_CONT.y, BTN_CONT.w, BTN_CONT.h)) titleSel = 0;
else if (inRect(q.x, q.y, BTN_NEW.x, BTN_NEW.y, BTN_NEW.w, BTN_NEW.h)) titleSel = 1;
