for (let k = 0; k < 3; k++) { ps.pos[t3 + k] = ps.pos[f3 + k]; ps.vel[t3 + k] = ps.vel[f3 + k]; }
for (let k = 0; k < 4; k++) ps.col[t4 + k] = ps.col[f4 + k];
