au = { ctx: ctx, src: [o1, o2, ns, ws], nodes: [o1, o2, g2, lp, eg, ns, bp, sg, ws, hp, wg], o1: o1, o2: o2, lp: lp, eg: eg, bp: bp, sg: sg, wg: wg };
